// ============================================================================
// SETUP
// ============================================================================

const MAX: u32 = 5;

pub struct Config {
    value: u32,
}

// ============================================================================
// END SETUP
// ============================================================================

// ============================================================================
// BODY
// ============================================================================

impl Config {
    pub fn new() -> Self {
        Config { value: MAX }
    }

    pub fn process(&self) -> u32 {
        self.value * 2
    }
}

// WRONG: tests in BODY block — should be in CLOSING Cv
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn new_creates_config() {
        let c = Config::new();
        assert_eq!(c.value, 5);
    }

    #[test]
    fn process_doubles() {
        let c = Config::new();
        assert_eq!(c.process(), 10);
    }
}

